import type { ValidatedNEA } from "../Validated";
import { InvalidObjectError, ValueNotObjectError } from "../ValidationErrors";
import type { OptionalKeys, RequiredKeys, UnwrappedValueFromValidator } from "./ObjectTypes";
import type { ValidatorNEA } from "./Types";
/**
 * Returns a validator that takes an object and determines
 * whether or not it can be transformed into an object of
 * the specified type.
 * The success object type will be an
 * intersection of its validated key-values and any object
 * key-values that were not processed.
 *
 * Use this function when you want the success type to be
 * determined by the property validators and the object
 * being validated.
 *
 * @param propertyValidators A dictionary of validators
 *     to be applied to
 *     values of the object passed in to the validator.
 *     If the object has a key that does not appear in the
 *     validator dictionary, the value is just copied over
 *     to the resultant object.
 * @internal
 */
export declare function asPartialObject<TValidators extends Record<string, ValidatorNEA>>(propertyValidators: TValidators): <T>(obj: T) => ValidatedNEA<ValueNotObjectError | InvalidObjectError, Omit<T, keyof TValidators> & {
    [K in RequiredKeys<TValidators>]: UnwrappedValueFromValidator<TValidators[K]>;
} & {
    [K in OptionalKeys<TValidators>]?: NonNullable<UnwrappedValueFromValidator<TValidators[K]>>;
}>;
